#!/usr/bin/env bash
# Regenerates every screenshot in docs/screenshots from the built UI (mock
# data, real WebKitGTK through scripts/ui-shot.py). Player shots play files
# from MEDIA_ROOT: any folder laid out like the fixture paths
# (Skool/<group>/<NN - course>/...). With no MEDIA_ROOT and ffmpeg installed,
# placeholder clips are generated by scripts/ui-media-stub.py.
#
#   pnpm --dir ui build && [ONLY=youtube] scripts/ui-shots.sh [out-dir]
#
# Shots are taken at device scale 2 and written at 1x, quantised, into
# docs/screenshots (or out-dir).
set -euo pipefail
cd "$(dirname "$0")/.."
OUT=${1:-docs/screenshots}
RAW=$(mktemp -d)
trap 'rm -rf "$RAW"' EXIT
if [ -z "${MEDIA_ROOT:-}" ] && command -v ffmpeg >/dev/null; then
  MEDIA_ROOT=$RAW/media
  python3 scripts/ui-media-stub.py "$MEDIA_ROOT" >/dev/null
fi
MEDIA_ROOT=${MEDIA_ROOT:-/nonexistent}

MEDIA=()
[ -d "$MEDIA_ROOT" ] && MEDIA=(--media-root "$MEDIA_ROOT")
SCROLL='const m=document.querySelector("main");m.style.scrollBehavior="auto";'

# Lesson and group ids from the fixture.
read -r SKOOL_LESSON HOT_GROUP HOT_LESSON RES_LESSON < <(python3 - <<'EOF'
import json, urllib.parse as u
d = json.load(open("ui/src/lib/mock/library.json"))
q = lambda s: u.quote(s, safe="")
fh = d["platforms"][0]["groups"][0]
c5 = fh["courses"][4]["sections"][2]["lessons"][5]
res = next(l for c in fh["courses"] for s in c["sections"] for l in s["lessons"] if l["resources"] and l["hasVideo"])
hot = d["platforms"][1]["groups"][1]
vid = next(l for s in hot["courses"][0]["sections"] for l in s["lessons"]
           if any(r["kind"] == "video" for r in l["resources"]) and any(r["kind"] == "file" for r in l["resources"]))
print(q(fh["id"]) + "/" + q(c5["key"]), q(hot["id"]), q(hot["id"]) + "/" + q(vid["key"]), q(fh["id"]) + "/" + q(res["key"]))
EOF
)

shot() { # name size args...   (ONLY=<substring> limits which shots run)
  local name=$1 size=$2; shift 2
  [[ -n "${ONLY:-}" && "$name" != *"$ONLY"* ]] && return 0
  timeout 60 python3 scripts/ui-shot.py -W "${size%x*}" -H "${size#*x}" --out "$RAW/$name-$size.png" "$@" >/dev/null
}

for size in 760x520 1024x640 1280x800; do
  shot inicio "$size" --route "#/"
  # Hero preview of the real lesson video (needs MEDIA_ROOT; the mock alone shows the poster).
  [ ${#MEDIA[@]} -gt 0 ] && shot inicio-video "$size" "${MEDIA[@]}" --route "#/" --wait 4000
  shot biblioteca "$size" --route "#/library"
  shot curso "$size" --route "#/course/ACADEMIA%20AURORA/5"
  shot reproductor "$size" "${MEDIA[@]}" --route "#/watch/$SKOOL_LESSON" --wait 3500
  shot plataformas-selector "$size" --route "#/downloads"
  shot plataformas-udemy "$size" --route "#/downloads/udemy"
  shot plataformas-skool "$size" --page "index.html?skool=connected" --route "#/downloads" \
    --js 'document.querySelector("a.tile[data-id=skool]").click()' --after 1200
done
# Poster card previews with real video (needs MEDIA_ROOT)
if [ ${#MEDIA[@]} -gt 0 ]; then
  for size in 760x520 1280x800; do
    shot tarjetas-inicio "$size" "${MEDIA[@]}" --route "#/" --wait 2500 --after 3500 \
      --js 'const m=document.querySelector("main");m.style.scrollBehavior="auto";m.scrollTop=document.querySelector(".shelf").offsetTop-40'
    shot tarjetas-biblioteca "$size" "${MEDIA[@]}" --route "#/library" --wait 2500 --after 3500
    shot tarjetas-curso-skool "$size" "${MEDIA[@]}" --route "#/course/ACADEMIA%20AURORA/5" --wait 2500 --after 3000
    shot tarjetas-curso-hotmart "$size" "${MEDIA[@]}" --route "#/course/$HOT_GROUP/1" --wait 2500 --after 3000
  done
fi

# Thumbnails need ffmpeg: dismissible note in Biblioteca (S11.ui)
shot biblioteca-sin-ffmpeg 1280x800 --page "index.html?ffmpeg=missing" --route "#/library" --after 1500

# Udemy wizard (S9.udemy)
for size in 760x520 1280x800; do
  shot udemy-1-sesion "$size" --route "#/downloads/udemy" --after 1200
  shot udemy-1-esperando "$size" --page "index.html?udemy=waiting" --route "#/downloads/udemy" --after 1200 \
    --js "setTimeout(()=>document.querySelector('.panel .btn-primary').click(),600)"
  shot udemy-1-bot "$size" --page "index.html?udemy=bot" --route "#/downloads/udemy" --after 1500 \
    --js "setTimeout(()=>document.querySelector('.panel .btn-primary').click(),600)"
  shot udemy-2-opciones "$size" --page "index.html?udemy=connected" --route "#/downloads/udemy" --after 1200
  shot udemy-3-comprobando "$size" --page "index.html?udemy=running" --route "#/downloads/udemy" --after 3500 \
    --js "setTimeout(()=>document.querySelector('.panel .btn-primary').click(),600)"
  shot udemy-4-resultado "$size" --page "index.html?udemy=result" --route "#/downloads/udemy" --after 1500
  shot udemy-4-cancelado "$size" --page "index.html?udemy=cancelled" --route "#/downloads/udemy" --after 1500
done

# YouTube (S8.B)
YT_TYPE() { echo "const i=document.querySelector('input[type=url]');i.value='$1';i.dispatchEvent(new Event('input',{bubbles:true}));"; }
for size in 760x520 1024x640 1280x800; do
  shot youtube-vacio "$size" --route "#/downloads/youtube"
  shot youtube-video "$size" --route "#/downloads/youtube" --js "$(YT_TYPE 'https://www.youtube.com/watch?v=dQw4w9WgXcQ')" --after 1800
  shot youtube-lista "$size" --route "#/downloads/youtube" --after 1900 \
    --js "$(YT_TYPE 'https://www.youtube.com/playlist?list=PLguitarra01')setTimeout(()=>document.querySelectorAll('.items input[type=checkbox]')[4].click(),1400)"
  shot youtube-descargando "$size" --page "index.html?youtube=downloading" --route "#/downloads/youtube" --after 1500
  shot youtube-avisos "$size" --page "index.html?youtube=report-warn" --route "#/downloads/youtube" --after 1200 \
    --js "setTimeout(()=>document.querySelectorAll('details.kind').forEach(d=>d.open=true),600)"
  shot youtube-error-ytdlp "$size" --page "index.html?youtube=noytdlp" --route "#/downloads/youtube" \
    --js "$(YT_TYPE 'https://www.youtube.com/watch?v=dQw4w9WgXcQ')" --after 1800
  shot youtube-error-enlace "$size" --route "#/downloads/youtube" --js "$(YT_TYPE 'https://www.youtube.com/@canal')" --after 900
  shot youtube-error-privado "$size" --route "#/downloads/youtube" --js "$(YT_TYPE 'https://www.youtube.com/watch?v=PRIVADO0000')" --after 1800
  shot biblioteca-youtube "$size" --route "#/library/youtube"
  shot youtube-curso "$size" --route "#/course/youtube%2FCurso%20de%20guitarra%20ac%C3%BAstica%20desde%20cero/1"
done

CHANGE='[...document.querySelectorAll("button")].find(b=>b.textContent.includes("Cambiar carpeta")).click()'
USE="setTimeout(()=>[...document.querySelectorAll('button')].find(b=>b.textContent.includes('Usar esta carpeta')).click(),400)"
UPD_CHECK='[...document.querySelectorAll("button")].find(b=>b.textContent.includes("Buscar actualizaciones")).click()'
UPD_SCROLL='document.querySelector("[aria-labelledby^=upd-h]").scrollIntoView({block:"start"})'
UPD_INSTALL='[...document.querySelectorAll("button")].find(b=>/Instalar y reiniciar|Descargar y verificar/.test(b.textContent)).click()'
UPD_YES='[...document.querySelectorAll("button")].find(b=>b.textContent.trim()==="Instalar").click()'
OPEN_DELETE='document.querySelector(".card .kebab").click();setTimeout(()=>document.querySelector("[role=menuitem]").click(),150)'
for size in 760x520 1280x800; do
  shot ajustes "$size" --route "#/settings"
  shot ajustes-carpeta-existente "$size" --page "index.html?pick=existing" --route "#/settings" --js "$CHANGE" --after 900
  shot ajustes-carpeta-vacia "$size" --page "index.html?pick=empty" --route "#/settings" --js "$CHANGE" --after 900
  shot ajustes-carpeta-error "$size" --page "index.html?pick=error" --route "#/settings" --js "$CHANGE;$USE" --after 1200
  shot ajustes-act-reposo "$size" --route "#/settings" --js "$UPD_SCROLL" --after 700
  shot ajustes-act-disponible "$size" --page "index.html?update=available" --route "#/settings" \
    --js "$UPD_CHECK;setTimeout(()=>{document.querySelector('.notes summary').click();$UPD_SCROLL},500)" --after 1200
  shot ajustes-act-privado "$size" --page "index.html?update=unauthorized" --route "#/settings" \
    --js "$UPD_CHECK;setTimeout(()=>{$UPD_SCROLL},500)" --after 1200
  shot ajustes-act-al-dia "$size" --page "index.html?update=current" --route "#/settings" \
    --js "$UPD_CHECK;setTimeout(()=>{$UPD_SCROLL},500)" --after 1200
  for st in "confirmando:available:" "descargando:install-ok&hold=downloading:$UPD_YES" "instalando:install-ok&hold=installing:$UPD_YES" \
    "firma:install-sig:$UPD_YES" "manual:install-manual:$UPD_YES"; do
    IFS=: read -r nm q yes <<<"$st"
    step=""
    [ -n "$yes" ] && step="setTimeout(()=>{$yes},300);"
    shot "ajustes-inst-$nm" "$size" --page "index.html?update=$q" --route "#/settings" \
      --js "$UPD_CHECK;setTimeout(()=>{$UPD_INSTALL;${step}setTimeout(()=>{$UPD_SCROLL},900)},500)" --after 5200
  done
  shot biblioteca-eliminar-menu "$size" --route "#/library" --js 'document.querySelector(".card .kebab").click()' --after 600
  shot eliminar-dialogo "$size" --route "#/library" --js "$OPEN_DELETE" --after 1200
  shot eliminar-descarga-en-curso "$size" --page "index.html?delete=running" --route "#/library" --js "$OPEN_DELETE" --after 1200
  shot eliminar-definitivo "$size" --route "#/library" --after 1500 \
    --js "$OPEN_DELETE;setTimeout(()=>{document.querySelector('dialog .disclosure').click();document.querySelector('dialog input[type=checkbox]').click()},700)"
  shot eliminar-error-papelera "$size" --page "index.html?delete=trashfail" --route "#/library" --after 1500 \
    --js "$OPEN_DELETE;setTimeout(()=>document.querySelector('dialog .trash').click(),700)"
  shot eliminar-hecho "$size" --route "#/library" --after 1800 \
    --js "$OPEN_DELETE;setTimeout(()=>document.querySelector('dialog .trash').click(),700)"
done
shot plataformas-pluralsight 1280x800 --route "#/downloads/pluralsight"
shot reproductor-cine 1280x800 "${MEDIA[@]}" --route "#/watch/$SKOOL_LESSON" --wait 3500 \
  --js 'window.dispatchEvent(new KeyboardEvent("keydown",{key:"t",bubbles:true}))'
shot reproductor-recursos 1280x800 "${MEDIA[@]}" --route "#/watch/$RES_LESSON" --wait 3500 --js "${SCROLL}m.scrollTop=560"

for size in 760x520 1280x800; do
  # Skool download states
  for st in "desconectado||" "cookies||document.querySelector('.disclosure').click();setTimeout(()=>{${SCROLL}m.scrollTop=m.scrollHeight},100)" \
            "esperando|waiting|document.querySelector('.btn-primary').click()" "conectado|connected|" "descargando|downloading|" \
            "completa|report-ok|" "avisos|report-warn|setTimeout(()=>document.querySelectorAll('details.kind').forEach(d=>d.open=true),500)" \
            "errores|report-err|" "cancelada|cancelled|" "sin-biblioteca|nolibrary|document.querySelector('.item .btn-quiet').click()"; do
    IFS='|' read -r n p js <<<"$st"
    q=""; [ -n "$p" ] && q="?skool=$p"
    shot "descargas-$n" "$size" --page "index.html$q" --route "#/downloads/skool" --js "$js" --after 1300
  done
  # Hotmart download states
  for st in "desconectado||" "cookies||document.querySelector('.disclosure').click();setTimeout(()=>{${SCROLL}m.scrollTop=m.scrollHeight},100)" \
            "conectado|connected|" "descargando|downloading|" "completa|report-ok|" \
            "avisos|report-warn|setTimeout(()=>document.querySelectorAll('details.kind').forEach(d=>d.open=true),500)" "errores|report-err|"; do
    IFS='|' read -r n p js <<<"$st"
    q=""; [ -n "$p" ] && q="?hotmart=$p"
    shot "hotmart-descargas-$n" "$size" --page "index.html$q" --route "#/downloads/hotmart" --js "$js" --after 1300
  done
  shot hotmart-biblioteca-todas "$size" --route "#/library"
  shot hotmart-biblioteca-hotmart "$size" --route "#/library/hotmart"
  shot hotmart-biblioteca-skool "$size" --route "#/library/skool"
  shot hotmart-curso "$size" --route "#/course/$HOT_GROUP/1"
  shot hotmart-clase "$size" --route "#/watch/$HOT_LESSON" --js "${SCROLL}m.scrollTop=(document.querySelector('#vid-h')?.offsetTop??40)-40"
  shot hotmart-inicio-estantes "$size" --route "#/" --js "${SCROLL}m.scrollTop=m.scrollHeight"
done

python3 - "$RAW" "$OUT" <<'EOF'
import glob, os, sys
from PIL import Image
raw, out = sys.argv[1:]
for f in sorted(glob.glob(os.path.join(raw, "*.png"))):
    im = Image.open(f).convert("RGB")
    im = im.resize((im.width // 2, im.height // 2), Image.LANCZOS)
    im.quantize(colors=192, method=Image.Quantize.MEDIANCUT, dither=Image.Dither.NONE).save(
        os.path.join(out, os.path.basename(f)), optimize=True)
print(len(glob.glob(os.path.join(raw, "*.png"))), "screenshots written to", out)
EOF
